export default function App() {
 const [showB, setShowB] = useState(true);
 return (
 <div>
 <Counter />
 {showB && <Counter />}
 <label>
 <input
 type="checkbox"
 checked={showB}
 onChange={e => {
 setShowB(e.target.checked)
 }}
